package ca.trailbound.app;
import android.content.*;import androidx.test.ext.junit.runners.AndroidJUnit4;import androidx.test.platform.app.InstrumentationRegistry;import androidx.test.core.app.ActivityScenario;import org.junit.*;import org.junit.runner.RunWith;import static org.junit.Assert.*;import java.io.*;import java.util.zip.*;
@RunWith(AndroidJUnit4.class)
public class WebUpdateTest {
 private void shell(String command)throws Exception {try(android.os.ParcelFileDescriptor p=InstrumentationRegistry.getInstrumentation().getUiAutomation().executeShellCommand(command);InputStream in=new android.os.ParcelFileDescriptor.AutoCloseInputStream(p)){in.readAllBytes();}}
 private String evaluate(ActivityScenario<MainActivity> activity,String script)throws Exception {java.util.concurrent.CountDownLatch latch=new java.util.concurrent.CountDownLatch(1);java.util.concurrent.atomic.AtomicReference<String> result=new java.util.concurrent.atomic.AtomicReference<>("null");activity.onActivity(a->{android.webkit.WebView web=(android.webkit.WebView)((android.view.ViewGroup)a.findViewById(android.R.id.content)).getChildAt(0);web.evaluateJavascript(script,value->{result.set(value);latch.countDown();});});assertTrue(latch.await(5,java.util.concurrent.TimeUnit.SECONDS));return result.get();}
 private void assets(Context c,ZipOutputStream zip,String path,String sw,String revision)throws Exception {String[] children=c.getAssets().list(path);if(children!=null&&children.length>0){for(String child:children)assets(c,zip,path.isEmpty()?child:path+"/"+child,sw,revision);return;}byte[] body;try(InputStream in=c.getAssets().open(path)){body=in.readAllBytes();}String name=sw.contains("'./"+path+".gz'")?path+".gz":path;if(path.equals("release.json"))body=("{\"revision\":\""+revision+"\",\"minBridge\":1,\"version\":\"test\"}").getBytes(java.nio.charset.StandardCharsets.UTF_8);if(path.equals("index.html"))body=(new String(body,java.nio.charset.StandardCharsets.UTF_8)+"<meta name=update-proof content=verified>").getBytes(java.nio.charset.StandardCharsets.UTF_8);zip.putNextEntry(new ZipEntry(name));zip.write(body);zip.closeEntry();}
 @Test public void verifiedReleaseAppliesOfflineAndKeepsStorageWhileRecordingDefersActivation()throws Exception {
  Context c=InstrumentationRegistry.getInstrumentation().getTargetContext();WebUpdater updater=new WebUpdater(c);updater.prefs.edit().clear().commit();String revision="cccccccccccccccccccccccccccccccccccccccc";TrackDb db=new TrackDb(c);db.finish();shell("svc wifi disable");shell("svc data disable");
  try{
   try(ActivityScenario<MainActivity> activity=ActivityScenario.launch(MainActivity.class)){for(int i=0;i<80;i++){if("true".equals(evaluate(activity,"Boolean(document.getElementById('browse-tct')&&!document.getElementById('browse-tct').disabled)")))break;Thread.sleep(250);}assertEquals("true",evaluate(activity,"localStorage.setItem('update-sentinel','kept');(()=>{const q=indexedDB.open('trailbound',1);q.onsuccess=()=>{const tx=q.result.transaction('settings','readwrite');tx.objectStore('settings').put('kept','update-sentinel');tx.oncomplete=()=>{document.body.dataset.backupSeeded='yes';q.result.close();};};return true;})()"));for(int i=0;i<40;i++){if("true".equals(evaluate(activity,"document.body.dataset.backupSeeded==='yes'")))break;Thread.sleep(100);}assertEquals("true",evaluate(activity,"document.body.dataset.backupSeeded==='yes'"));}
   String sw;try(InputStream in=c.getAssets().open("sw.js")){sw=new String(in.readAllBytes(),java.nio.charset.StandardCharsets.UTF_8);}ByteArrayOutputStream out=new ByteArrayOutputStream();try(ZipOutputStream zip=new ZipOutputStream(out)){assets(c,zip,"",sw,revision);}File file=new File(c.getCacheDir(),"update-fixture.zip");try(OutputStream f=new FileOutputStream(file)){f.write(out.toByteArray());}updater.stage(out.toByteArray(),revision,WebUpdateFiles.hash(file));file.delete();
   String track=db.start("Update persistence test");assertFalse(updater.activateReady(db.active()!=null));assertEquals(track,db.active());assertEquals("",updater.activeRevision());db.finish();assertTrue(updater.activateReady(false));assertEquals(revision,updater.activeRevision());assertTrue(db.snapshot().contains("Update persistence test"));
   try(ActivityScenario<MainActivity> activity=ActivityScenario.launch(MainActivity.class)){boolean ready=false;for(int i=0;i<100;i++){if("true".equals(evaluate(activity,"Boolean(document.querySelector('meta[name=update-proof]')&&document.getElementById('browse-tct')&&!document.getElementById('browse-tct').disabled)"))){ready=true;break;}Thread.sleep(250);}assertTrue("Downloaded release must boot and load its TCT data without internet",ready);assertEquals("\"kept\"",evaluate(activity,"localStorage.getItem('update-sentinel')"));evaluate(activity,"(()=>{const q=indexedDB.open('trailbound',1);q.onsuccess=()=>{const get=q.result.transaction('settings').objectStore('settings').get('update-sentinel');get.onsuccess=()=>{document.body.dataset.backupRestored=get.result;q.result.close();};};return true;})()");for(int i=0;i<40;i++){if("true".equals(evaluate(activity,"document.body.dataset.backupRestored==='kept'")))break;Thread.sleep(100);}assertEquals("true",evaluate(activity,"document.body.dataset.backupRestored==='kept'"));assertEquals("true",evaluate(activity,"document.getElementById('browser-recorder').hidden && !document.getElementById('native-recorder').hidden"));}
  }finally{updater.prefs.edit().clear().commit();db.finish();db.close();shell("svc wifi enable");shell("svc data enable");}
 }
}
